import React, { useLayoutEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { MotionPathPlugin } from 'gsap/MotionPathPlugin';

gsap.registerPlugin(ScrollTrigger, MotionPathPlugin);

const HungerAnimation = ({ onApply }) => {
    const sectionRef = useRef(null);
    const b1Ref = useRef(null);
    const mgBackRef = useRef(null);
    const mgFrontRef = useRef(null);

    useLayoutEffect(() => {
        const ballTL = gsap.timeline({ repeat: -1, defaults: { duration: 2, ease: 'none' } })
            .to(b1Ref.current, {
                scale: 0.75,
                motionPath: {
                    path: "#b1Path",
                    align: "#b1Path",
                    start: 0.25,
                    end: 0.75
                }
            }, 0)
            .add(() => {
                if (mgBackRef.current && b1Ref.current) mgBackRef.current.append(b1Ref.current);
            }, 1)
            .to(b1Ref.current, {
                scale: 1,
                motionPath: {
                    path: "#b1Path",
                    align: "#b1Path",
                    start: 0.75,
                    end: 1.25
                }
            }, 2)
            .add(() => {
                if (mgFrontRef.current && b1Ref.current) mgFrontRef.current.append(b1Ref.current);
            }, 3)
            .to('#b1-dark', { scaleY: 0.8, ease: 'sine.inOut', transformOrigin: '88% 80%', yoyo: true, repeat: 1 }, 0)
            .to('#b1 ellipse', { scale: 0.6, ease: 'sine.inOut', transformOrigin: '0 50%', yoyo: true, repeat: 1 }, 0)
            .timeScale(0.25);

        const ctx = gsap.context(() => {
            gsap.timeline({
                scrollTrigger: {
                    trigger: sectionRef.current,
                    start: 'top bottom',
                    end: 'bottom top',
                    scrub: 0.1
                }
            })
            .to('.ring2', { y: 99, scaleY: 1.08 }, 0)
            .fromTo('.ring1', { y: 2 }, { y: 60, skewY: 3 }, 0);
        }, sectionRef);

        return () => {
            ballTL.kill();
            ctx.revert();
        };
    }, []);

    return (
        <section ref={sectionRef} className="hunger-animation-section relative bg-black py-20 overflow-hidden">
            {/* Blue ambient glow */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[700px] bg-[#4A749B]/10 blur-[150px] rounded-full pointer-events-none"></div>
            <div className="max-w-7xl mx-auto px-6 relative z-20 text-center mb-12">
                <h2 className="font-headline text-5xl md:text-7xl font-black leading-tight mb-4 text-white">
                    You have the <span className="font-accent text-tertiary italic">hunger.</span><br/>
                    <span className="text-white">We have the <span className="font-accent text-tertiary italic">match.</span></span>
                </h2>
                <button 
                    onClick={onApply}
                    className="mt-10 bg-tertiary text-white px-12 py-5 rounded-2xl font-headline text-xl font-black uppercase tracking-tight hover:scale-105 active:scale-95 transition-all shadow-[0_0_30px_rgba(74,116,155,0.5)]"
                >
                    Apply Now
                </button>
            </div>

            <svg xmlns="http://www.w3.org/2000/svg" fill="#000000" stroke="#000000" strokeWidth="1.8" viewBox="10 0 970 200" className="w-full relative mt-[-5vw]">
                <defs>
                    <mask id="m1" fill="#fff">
                        <path d="M999,172c0,32.9-240.3,39.3-514,6.4S1,98.2,1,64c0-37.4,268.8-36.5,542.5-3.6S999,144.6,999,172z M520,64.6 c-193.6-24.6-409.4-26.4-410,5s167.8,65.7,361.4,90.3s421.1,27.9,421.7-3.6S713.6,89.2,520,64.6z"/>
                    </mask>
                    <mask id="m2" fill="#fff">
                        <path d="M782 58c0 19-135.6 40-290.5 41.5S217 89.8 217 70c0-18.3 128.9-37.2 283.9-38.8C655.8 29.6 782 42.1 782 58zM508.1 36.3c-86.4 0-182.8 11.2-183 25-.3 13.8 74.9 19.5 161.3 19.5s188-11.2 188.2-25-80-19.5-166.5-19.5z"/>
                    </mask>
                    <mask id="m3" fill="#fff">
                        <path d="M674.7,55.7c-0.3,13.8-101.8,25-188.2,25s-161.6-5.6-161.3-19.5L325-0.5h349L674.7,55.7z"/>
                    </mask>
                    <mask id="m4" fill="#fff">
                        <path d="M110 69.7c-.6 31.5 167.8 65.7 361.4 90.3s421.1 27.9 421.7-3.6L893 0H109l1 69.7z"/>
                    </mask>
                    <mask id="m5" fill="#fff" strokeWidth="1">
                        <circle id="c1" cx="709" cy="42" r="20"/>
                    </mask>
                    <mask id="m6" fill="#fff" strokeWidth="1">
                        <circle id="c2" cx="899.2" cy="144.2" r="27.2"/>
                    </mask>
                </defs>

                <g className="ring3">
                    <path d="M543.5 60.6C269.8 27.7 1 26.8 1 64.2v386h998v-278c0-27.4-181.8-78.7-455.5-111.6z"/>
                    <image mask="url(#m1)" y="35" width="999" height="170" preserveAspectRatio="none" href="data:image/jpg;base64,"/>
                    <g className="mg-back" ref={mgBackRef}></g>
                    <mask id="m2" fill="#fff">
                        <path d="M782 58c0 19-135.6 40-290.5 41.5S217 89.8 217 70c0-18.3 128.9-37.2 283.9-38.8C655.8 29.6 782 42.1 782 58zM508.1 36.3c-86.4 0-182.8 11.2-183 25-.3 13.8 74.9 19.5 161.3 19.5s188-11.2 188.2-25-80-19.5-166.5-19.5z"/>
                    </mask>
                    <mask id="m4" fill="#fff">
                        <path d="M110 69.7c-.6 31.5 167.8 65.7 361.4 90.3s421.1 27.9 421.7-3.6L893 0H109l1 69.7z"/>
                    </mask>

                    <g mask="url(#m3)">
                        <g className="ring1">
                            <path fill="#1a3a5c" d="M415 8.8C415 3 454.3-1 501.7 1S588 9 588 14M415 8.8V90h173V14"/>
                            <rect x="536" y="14" width="45" height="70" fill="#1a3a5c"/>
                            <path fill="#4A749B" d="M588 14c0 6-41.7 10.4-89.1 8.4S415 15 415 8.8C415 3 454.3-1 501.7 1S588 9 588 14z"/>    
                            <path d="M501 4c-16.6 0-35 2-35 4.5s14.4 3.5 31 3.5 36-1.5 36-4-15.4-4-32-4z"/>
                            <mask id="m3" fill="#fff">
                                <path d="M674.7,55.7c-0.3,13.8-101.8,25-188.2,25s-161.6-5.6-161.3-19.5L325-0.5h349L674.7,55.7z"/>
                            </mask>
                        </g>
                    </g>

                    <g className="mg-front" ref={mgFrontRef}>
                        <g id="b1" ref={b1Ref}>
                            <ellipse cx="734" cy="61" rx="33" ry="4" opacity="0.8"/>
                            <use fill="#4A749B" href="#c1"/>
                            <g mask="url(#m5)">
                                <circle id="b1-dark" cx="724" cy="56" r="20" opacity="0.5"/>
                            </g>
                        </g>
                    </g>
                    <path id="b1Path" fill="none" stroke="none" d="M693.8,23.9C693.5,37.4,597,54,462.5,54C296,54,250,43.7,250.2,30.3C250.5,16.8,369,3,487.2,3
                        C606,3,694,10.4,693.8,23.9z"/>
                </g>
                
                <g id="b2">
                    <ellipse cx="933.8" cy="172.6" rx="7" ry="46" transform="rotate(-83.812 933.77606 172.57357)" />
                    <use fill="#4A749B" href="#c2"/>
                    <circle mask="url(#m6)" cx="917.8" cy="162.8" r="27.2" opacity="0.7"/>
                </g>
                <use href="#b2" x="-853" y="-84" transform="scale(0.87)" />
                
                <g mask="url(#m4)">
                    <g className="ring2">
                        <path fill="#2a5580" d="M217 70c0-18.3 128.9-37.2 283.9-38.8C655.8 29.6 782 42.1 782 58M217 70v260h565V58"/>
                        <rect x="646" y="64" width="125" height="127" fill="#2a5580"/>
                        <path d="M782 58c0 19-135.6 40-290.5 41.5S217 89.8 217 70c0-18.3 128.9-37.2 283.9-38.8C655.8 29.6 782 42.1 782 58z" fill="#2a5580"/>
                        <image mask="url(#m2)" width="565" height="69" x="217" y="31" preserveAspectRatio="none" href="data:image/jpg;base64,"/>
                    </g>
                </g>
            </svg>

            <style>{`
                .hunger-animation-section {
                    perspective: 1000px;
                }
            `}</style>
        </section>
    );
};

export default HungerAnimation;
